#include "Application.hpp"
#include <SDL3/SDL.h>
namespace th075::sdl {
bool Application::tick(const BattleSystemInput& input,u32 milliseconds){now=milliseconds;if(!initialized||!error.empty())return false;++frame;const auto before=sceneCode;if(sceneCode&0xff00){sceneCode=fade.advance(sceneCode,settings.deviceRefresh!=0,*this);if(sceneCode!=before&&!(sceneCode&0xf00)&&(sceneCode&0xf000)){if(!enter(u8(sceneCode)))return false;}}else{u16 next=sceneCode;const auto menu=menu_input(input);switch(scene){case 0:{BattleStoryEvents story(battle->simulation.characters[0]->actor,battle->simulation.characters[1]->actor,characterAssets[0].script,battle->simulation.story,dialogueCache,*this,battle->controls.recordingFastForward);next=u16(battle->advance(input,story));break;}case 1:draw_scene();if(!loaderReady){if(!load_battle())return false;loaderReady=true;if(selection.mode==GameMode::Story&&selection.storyStage>7)next=0x1108;else next=0x2000;}break;case 2:{draw_scene();graphics.present();TitleInput ti;ti.players=input.players;ti.escape=menu.escape;const auto transition=title.advance(ti,now,selection,loadingReplay.random,static_cast<CharacterSelectSignals&>(*this));switch(transition){case SceneTransition::CharacterSelect:next=0x2203;break;case SceneTransition::ReplayMenu:next=0x2205;break;case SceneTransition::MusicRoom:next=0x220c;break;case SceneTransition::ResultList:next=0x220e;break;case SceneTransition::Options:next=0x2209;break;case SceneTransition::Demonstration:pendingSession={};pendingSession.replayMode=1;next=0x2201;break;case SceneTransition::Opening:next=0x3304;break;case SceneTransition::Exit:exiting=true;break;default:break;}if(next!=scene)title.leave(selection);break;}case 3:{std::array<SelectInput,2> ci;for(u8 s=0;s<2;s++){ci[s].counts[0]=input.players[s].horizontal;ci[s].counts[1]=input.players[s].vertical;for(u8 i=0;i<4;i++)ci[s].counts[2+i]=input.players[s].buttons[i];ci[s].counts[6]=input.cancel[s];}select.poll(ci,menu.escape,selection);next=select.advance(selection,playerSettings,progress,loadingReplay.random,*this);break;}case 4:draw_scene();graphics.present();if(++logoFrames>=181||menu.confirm[0]==1||menu.confirm[1]==1)next=0x220d;break;case 5:next=replays.advance(menu,*this);break;case 6:{bool confirm=false;for(const auto& player:input.players)for(const auto button:player.buttons)confirm|=button==1;next=result.advance(confirm,battle->simulation.characters[0]->actor,battle->simulation.rules,battle->session,selection.difficulty,loading.characters[0]->next_story_stage(),u8(playback.rounds.size()),*this,selection.resumeStory);break;}case 7:case 10:{nameEntry.poll(menu,{input.cancel[0],input.cancel[1]},static_cast<NameEntrySignals&>(*this));next=nameEntry.advance(profile.workingName,pendingSession.replayMode==1,pendingSession.replayDisposition,*this);std::copy(profile.workingName.begin(),profile.workingName.end(),recording.header.begin());break;}case 8:{BattleStoryEvents story(loading.characters[0]->actor,loading.characters[1]->actor,characterAssets[0].script,loading.story,dialogueCache,*this,false);loading.characters[0]->actor.confirmCount=input.players[0].buttons[0];draw_scene();loading.characters[0]->advance_story(loading.characters[1]->actor,loading.story,story);graphics.present();if(loading.characters[0]->actor.dialogueFinished){if(selection.storyStage==10)next=0x110b;else{stop_music(40);fade_music(-10000,-300,1,1);next=pendingSession.scoreToBeat<u32(loading.characters[0]->actor.score)?0x220a:0x1102;}}break;}case 9:options.poll(menu);next=options.advance(settings,*this);break;case 11:case 13:next=cinema.advance(menu.confirm,now,loading.characters[0]?&loading.characters[0]->actor:nullptr,pendingSession.scoreToBeat,loading.story.route,pendingSession.replayDisposition,*this);break;case 12:next=music.advance({menu.vertical,menu.confirm,menu.cancel,menu.escape},profile.selection_unlocks(),*this);break;case 14:next=resultList.advance(menu,u32(cards.names.size()),*this);break;}if(next!=sceneCode)change(next);}audio.update(u32(SDL_GetTicks()));audio.pump();return error.empty()&&!exiting;}
void Application::draw_scene(){if(scene!=0)graphics.clear(0x0f000000);ImageRenderer images(zun,sceneImages);switch(scene){case 0:if(battle)battle->render();break;case 1:case 4:images.image(0,0,0,0xffffffff,0,0);break;case 2:{std::array<u32,4> textures;for(u8 i=0;i<4;i++)textures[i]=sceneImages.image(i).texture;title.render(zun,textures);break;}case 3:{ImageRenderer chars(zun,selectionCharacters),backgrounds(zun,selectionBackgrounds);select.render(images,chars,backgrounds,selection,playerSettings,progress);break;}case 5:replays.render(images);break;case 6:result.render(images,captureTexture,loading.characters[0]->actor,selection.difficulty);break;case 7:{ReplayFile view=recording;std::copy(profile.workingName.begin(),profile.workingName.end(),view.header.begin());nameEntry.render_replay(images,view,saveReplayPath.rfind("/save/",0)==0?saveReplayPath.substr(6):saveReplayPath,saveReplayOpponent,now);break;}case 8:{zun.depth(DepthMode::Disabled);zun.filter(Filter::Nearest);loading.characters[0]->render_story(selection.storyStage,zun,battleArt?battleArt->captions[0]:std::array<u32,4>{});if(loading.characters[0]->actor.notice.dialogueVisible)render();if(loading.story.fadeAlpha)zun.filled_rectangle({0,0,640,480},u32(loading.story.fadeAlpha)<<24|loading.story.fadeColor);break;}case 9:options.render(images,menuText,settings);break;case 10:nameEntry.render_score(images,profile.selected().ranking,now);break;case 11:case 13:cinema.render(images);break;case 12:music.render(images,musicArtwork);break;case 14:resultList.render(images,menuText,profile,u32(cards.names.size()));break;}}
bool Application::return_title(){if(!save_scores())return false;change(0x2202);return true;}
void Application::render_scene(){draw_scene();if(fade.style&&captureTexture){ImageRenderer images(zun,sceneImages);fade.render(images,captureTexture);}}void Application::present_scene(){graphics.present();}
void Application::render_selection(){draw_scene();}void Application::present_selection(){graphics.present();}void Application::prepare_battle(){pendingSession.replayMode=1;recordingFinished=false;}
void Application::render_options(){draw_scene();}void Application::present_options(){graphics.present();}void Application::save_settings(){save_scores();}
void Application::render_music_room(){draw_scene();}void Application::present_music_room(){graphics.present();}
void Application::render_cinema(){draw_scene();}void Application::present_cinema(){graphics.present();}
void Application::render_name_entry(){if(scene==10&&nameEntry.rank<10)profile.selected().ranking[nameEntry.rank].name=profile.workingName;draw_scene();}void Application::present_name_entry(){graphics.present();}
void Application::render_replays(){draw_scene();}void Application::present_replays(){graphics.present();}
void Application::render_result(){draw_scene();}void Application::present_result(){graphics.present();}
void Application::render_result_list(){draw_scene();}void Application::present_result_list(){graphics.present();}
}
